// Calibration chart, read from ledger/brier.md (generated by ledger/brier.py).
// One dot per scored bet, read from ledger/bets.jsonl (scored: true, an outcome, engine odds), marked by its referee.
// The buckets and the prose come from brier.md. brier.md's per-bet table is not parsed for dots: bets' event text can
// hold "|" characters, which shift its columns (that is how a false "human" dot once appeared).
import { header, esc, inline, num, wrapTables, outcomeOf, REFEREE, refMark, refKey } from "./common.js";
import { loadBets, loadBrierMd, loadPriorMd } from "./data.js";

header();
const el = (id) => document.getElementById(id);
const SVGNS = "http://www.w3.org/2000/svg";
const SIDE = {
  engine: { word: "Engine", hex: "#3987e5" },
  human: { word: "Human (Sean)", hex: "#e07a3f" },
};

// ---------- markdown table parsing ----------
const clean = (s) => String(s ?? "").replace(/\*\*|`/g, "").trim();
function parseTables(md) {
  const lines = md.split("\n");
  const out = [];
  let heading = "";
  for (let i = 0; i < lines.length; i++) {
    const L = lines[i];
    const h = L.match(/^#{1,4}\s+(.*)/);
    if (h) { heading = h[1].trim(); continue; }
    if (L.trim().startsWith("|") && lines[i + 1] && /^\s*\|[\s:|-]+\|\s*$/.test(lines[i + 1])) {
      const cells = (row) => row.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
      const headers = cells(L).map((c) => clean(c).toLowerCase());
      const rows = [];
      i += 2;
      while (i < lines.length && lines[i].trim().startsWith("|")) { rows.push(cells(lines[i])); i++; }
      i--;
      out.push({ heading, headers, rows: rows.map((r) => Object.fromEntries(headers.map((hh, j) => [hh, r[j] ?? ""]))) });
    }
  }
  return out;
}
const col = (row, ...needles) => {
  for (const n of needles) for (const k of Object.keys(row)) if (k.includes(n)) return row[k];
  return undefined;
};
const firstNum = (s) => { const m = clean(s).match(/-?\d*\.?\d+/); return m ? parseFloat(m[0]) : null; };
const afterEq = (s) => { const m = clean(s).match(/=\s*(-?\d*\.?\d+)/); return m ? parseFloat(m[1]) : firstNum(s); };
const interval = (s) => { const m = clean(s).match(/\[\s*(-?\d*\.?\d+)\s*,\s*(-?\d*\.?\d+)\s*\]/); return m ? [+m[1], +m[2]] : null; };

function readBrier(md, bets) {
  const tables = md ? parseTables(md) : [];
  const scoresT = tables.find((t) => t.headers.some((h) => h.includes("brier")) && t.headers.some((h) => h.includes("side")));
  const betT = tables.find((t) => /scored bet/i.test(t.heading) || (t.headers.includes("bet") && t.headers.some((h) => h.includes("outcome"))));
  const calT = tables.filter((t) => /calibration/i.test(t.heading) && t.headers.some((h) => h.includes("bucket")));
  const scores = {};
  for (const r of scoresT?.rows || []) {
    const side = clean(r.side).toLowerCase();
    const key = side.includes("secondary included") ? "engineAll"   // rule 15's sensitivity row, not the headline
      : side.startsWith("engine +") || side.includes("+") ? "both" : side.startsWith("human") ? "human" : "engine";
    scores[key] = {
      n: firstNum(col(r, "scored")), expected: firstNum(col(r, "expected")), observed: firstNum(col(r, "observed")),
      brier: firstNum(r["brier"]), base: firstNum(col(r, "base rate")), half: firstNum(col(r, "0.5")),
    };
  }
  void betT;
  const points = [], secondary = [];
  for (const b of bets) {
    const o = outcomeOf(b);
    if (o == null || b.raw?.scored !== true) continue;
    // Rule 15: a bet that re-scores a run an earlier bet was scored on counts once; it is kept for the sensitivity sentence only.
    if (b.raw?.secondary_of) { if (b.engine != null) secondary.push({ id: b.id, of: b.raw.secondary_of, p: b.engine, o }); continue; }
    if (b.engine != null) points.push({ side: "engine", id: b.id, p: b.engine, o, bet: b, event: b.oddsEvent, ref: b.referee });
    if (b.human != null) points.push({ side: "human", id: b.id, p: b.human, o, bet: b, event: b.oddsEvent, ref: b.referee });
  }
  const buckets = [];
  for (const t of calT) for (const r of t.rows) {
    const range = clean(col(r, "bucket"));
    const n = firstNum(r["bets"]);
    if (n) buckets.push({ side: "engine", range, n, p: firstNum(r["predicted"]), o: afterEq(r["observed"]), ci: interval(col(r, "interval")), raw: clean(r["observed"]) });
    const hn = firstNum(r["human: bets"]);
    if (hn) buckets.push({ side: "human", range, n: hn, p: firstNum(r["human: predicted"]), o: afterEq(r["human: observed"]), ci: interval(r["human: interval"] || ""), raw: clean(r["human: observed"]) });
  }
  return { scores, points, secondary, buckets, source: "bets.jsonl", tables };
}

// ---------- drawing ----------
function s(tag, attrs, parent) {
  const e = document.createElementNS(SVGNS, tag);
  for (const [k, v] of Object.entries(attrs)) if (v != null) e.setAttribute(k, v);
  if (parent) parent.append(e);
  return e;
}
function text(parent, x, y, str, attrs = {}) {
  const t = s("text", { x, y, fill: "#bcb8ae", "font-size": 15, ...attrs }, parent);
  t.textContent = str;
  return t;
}

function drawChart({ points, buckets }) {
  // Drawn at the box's real width so text stays at its stated size on a phone.
  const box = el("chart");
  const W = Math.max(320, Math.min(1100, box.clientWidth - 32));
  const narrow = W < 560;
  const M = { l: narrow ? 46 : 104, r: narrow ? 14 : 28, t: 20, b: 64 };
  const STRIP = narrow ? 46 : 58, GAP = 18, PLOT = narrow ? 240 : 300;
  const yTop = M.t, yPlot = yTop + STRIP + GAP, yBot = yPlot + PLOT + GAP;
  const H = yBot + STRIP + M.b;
  const x = (p) => M.l + p * (W - M.l - M.r);
  const y = (f) => yPlot + PLOT - f * PLOT;
  const svg = s("svg", { viewBox: `0 0 ${W} ${H}`, width: W, height: H, role: "img",
    "aria-label": `Calibration: ${points.length} scored bets plotted by stated odds and outcome` });

  // strips
  for (const [yy, word] of [[yTop, "Came true"], [yBot, "Did not"]]) {
    s("rect", { x: M.l, y: yy, width: W - M.l - M.r, height: STRIP, fill: "#20242a", rx: 6 }, svg);
    if (narrow) text(svg, W - M.r - 8, yy + 16, word, { fill: "#ece9e2", "font-size": 13, "font-weight": 700, "text-anchor": "end" });
    else text(svg, M.l - 14, yy + STRIP / 2 + 5, word, { "text-anchor": "end", fill: "#ece9e2", "font-size": 16, "font-weight": 700 });
  }
  // plot frame + grid
  for (const f of [0, 0.25, 0.5, 0.75, 1]) {
    s("line", { x1: M.l, x2: W - M.r, y1: y(f), y2: y(f), stroke: "#2c3138", "stroke-width": 1 }, svg);
    text(svg, M.l - 12, y(f) + 5, `${f * 100}%`, { "text-anchor": "end", "font-size": 14, fill: "#8d8a82" });
  }
  if (!narrow) {
    const yl = text(svg, 0, 0, "How often bets at these odds came true", { "font-size": 14, fill: "#8d8a82", "text-anchor": "middle" });
    yl.setAttribute("transform", `translate(${22} ${yPlot + PLOT / 2}) rotate(-90)`);
  }
  for (const p of [0, 0.25, 0.5, 0.75, 1]) {
    s("line", { x1: x(p), x2: x(p), y1: yTop, y2: yBot + STRIP, stroke: "#2c3138", "stroke-width": 1 }, svg);
    text(svg, x(p), yBot + STRIP + 22, `${p * 100}%`, { "text-anchor": "middle", "font-size": 14, fill: "#8d8a82" });
  }
  text(svg, M.l + (W - M.l - M.r) / 2, yBot + STRIP + 50, "Odds stated before any data", { "text-anchor": "middle", "font-size": 15, fill: "#bcb8ae" });
  // diagonal
  s("line", { x1: x(0), y1: y(0), x2: x(1), y2: y(1), stroke: "#6b7079", "stroke-width": 1.5 }, svg);
  if (!narrow) text(svg, x(0.80), y(0.80) - 10, "honest odds sit on this line", { "text-anchor": "end", "font-size": 14, fill: "#8d8a82", transform: `rotate(-${Math.atan(PLOT / (W - M.l - M.r)) * 180 / Math.PI} ${x(0.8)} ${y(0.8)})` });

  // buckets
  const hits = [];
  for (const b of buckets) {
    const c = b.side === "human" ? SIDE.human.hex : "#bcb8ae";
    if (b.ci) s("line", { x1: x(b.p), x2: x(b.p), y1: y(b.ci[0]), y2: y(b.ci[1]), stroke: c, "stroke-width": 2, "stroke-opacity": 0.55, "stroke-linecap": "round" }, svg);
    const r = 8;
    const g = s("g", { tabindex: 0, class: "pt" }, svg);
    s("path", { d: `M${x(b.p)} ${y(b.o) - r - 2}l${r + 2} ${r + 2}l${-(r + 2)} ${r + 2}l${-(r + 2)} ${-(r + 2)}Z`, fill: "#191c20" }, g);
    s("path", { d: `M${x(b.p)} ${y(b.o) - r}l${r} ${r}l${-r} ${r}l${-r} ${-r}Z`, fill: c }, g);
    s("rect", { x: x(b.p) - 16, y: y(b.o) - 16, width: 32, height: 32, fill: "transparent" }, g);
    if (!narrow) text(svg, x(b.p) + 14, y(b.o) + 5, `${b.raw.split("=")[0].trim().replace("/", " of ")}`, { "font-size": 14, fill: "#bcb8ae" });
    hits.push([g, `<div class="t-status">${SIDE[b.side].word} · odds ${esc(b.range)}</div>
      <div class="t-title">${b.n} bet${b.n === 1 ? "" : "s"}, average stated ${Math.round(b.p * 100)}%</div>
      <div>Came true: ${esc(b.raw)}${b.ci ? `<br>95% interval ${Math.round(b.ci[0] * 100)}–${Math.round(b.ci[1] * 100)}%` : ""}</div>`]);
  }

  // one dot per bet, stacked where they share odds
  // bets at the same odds and outcome stack evenly around the strip's middle
  const groups = new Map();
  for (const pt of points) { const key = `${pt.o}|${pt.p.toFixed(3)}`; if (!groups.has(key)) groups.set(key, []); groups.get(key).push(pt); }
  const step = narrow ? 14 : 18;
  for (const pt of points.sort((a, b) => a.p - b.p)) {
    const grp = groups.get(`${pt.o}|${pt.p.toFixed(3)}`);
    const i = grp.indexOf(pt);
    const baseY = (pt.o >= 0.5 ? yTop : yBot) + STRIP / 2;
    const cy = baseY + (i - (grp.length - 1) / 2) * Math.min(step, (STRIP - 18) / Math.max(1, grp.length - 1));
    const cx = x(pt.p);
    const ref = REFEREE[pt.ref] || REFEREE.model;
    const g = s("g", { tabindex: 0, class: "pt", "aria-label": `${pt.id}, ${ref.word.toLowerCase()}: odds ${Math.round(pt.p * 100)}%, ${pt.o ? "came true" : "did not"}` }, svg);
    if (pt.side === "human") { s("circle", { cx, cy, r: 9, fill: "#20242a" }, g); s("circle", { cx, cy, r: 7, fill: SIDE.human.hex }, g); }
    else g.insertAdjacentHTML("beforeend", refMark(pt.ref, cx, cy, 7, "#20242a"));
    s("rect", { x: cx - 14, y: cy - 12, width: 28, height: 24, fill: "transparent" }, g);
    const title = pt.bet?.title || pt.id;
    hits.push([g, `<div class="t-status">${pt.side === "human" ? SIDE.human.word : esc(ref.word)} · ${pt.o ? "came true" : "did not come true"}</div>
      <div class="t-title">${esc(title)}</div>
      <div>Odds before data: <b>${Math.round(pt.p * 100)}%</b>${pt.bet?.engineFirst != null && pt.side === "engine" && pt.bet.engineFirst !== pt.p ? ` (first written as ${Math.round(pt.bet.engineFirst * 100)}%)` : ""}</div>
      ${pt.event ? `<div class="t-meta">The odds were for: ${esc(pt.event)}</div>` : ""}
      <div class="t-meta">${esc(pt.id)} · ${esc(ref.what)}${pt.bet?.verdictAfterAudit ? ` · audit: ${esc(pt.bet.verdictAfterAudit)}` : ""}${pt.bet?.prereg ? ` · pre-registered in <code>${esc(pt.bet.prereg)}</code>` : ""}</div>`]);
  }
  el("chart").innerHTML = "";
  el("chart").append(svg);
  wireTips(hits);
}

let tip;
function wireTips(hits) {
  if (!tip) { tip = document.createElement("div"); tip.className = "tip"; tip.style.position = "fixed"; tip.hidden = true; document.body.append(tip); }
  const show = (g, html) => {
    tip.innerHTML = html; tip.hidden = false;
    const r = g.getBoundingClientRect();
    const tw = Math.min(340, window.innerWidth - 24);
    tip.style.maxWidth = tw + "px";
    let x = r.right + 12, y = r.top - 8;
    if (x + tw > window.innerWidth - 12) x = Math.max(12, r.left - tw - 12);
    if (y + tip.offsetHeight > window.innerHeight - 12) y = window.innerHeight - tip.offsetHeight - 12;
    tip.style.left = x + "px"; tip.style.top = Math.max(70, y) + "px";
  };
  for (const [g, html] of hits) {
    g.style.cursor = "pointer";
    g.addEventListener("mouseenter", () => show(g, html));
    g.addEventListener("focus", () => show(g, html));
    g.addEventListener("click", (e) => { e.stopPropagation(); show(g, html); });
    g.addEventListener("mouseleave", () => (tip.hidden = true));
    g.addEventListener("blur", () => (tip.hidden = true));
  }
  document.addEventListener("click", () => (tip.hidden = true));
  window.addEventListener("scroll", () => (tip.hidden = true), { passive: true });
}

function stat(label, value, note) {
  return `<div class="stat"><div class="label">${label}</div><div class="value">${value}</div><div class="note">${note}</div></div>`;
}

const brierOf = (pts) => (pts.length ? pts.reduce((a, p) => a + (p.p - p.o) ** 2, 0) / pts.length : null);
// One plain sentence: where the hits sat, by referee.
function hitsSentence(pts) {
  if (!pts.length) return "";
  const pc = (p) => `${Math.round(p * 100)}%`;
  const list = (a) => a.length < 2 ? a.join("") : `${a.slice(0, -1).join(", ")} and ${a.at(-1)}`;
  const hits = pts.filter((p) => p.o).sort((a, b) => a.p - b.p), miss = pts.filter((p) => !p.o).sort((a, b) => a.p - b.p);
  const by = ["model", "chip", "record"].map((k) => [k, hits.filter((p) => p.ref === k).length]).filter(([, n]) => n);
  const none = ["model", "chip", "record"].filter((k) => pts.some((p) => p.ref === k) && !hits.some((p) => p.ref === k));
  if (!hits.length) return `None of the ${pts.length} scored bets came true; they were given ${pc(miss[0].p)} to ${pc(miss.at(-1).p)}.`;
  return `The ${hits.length} hit${hits.length === 1 ? "" : "s"} sat at ${list(hits.map((p) => pc(p.p)))} ` +
    `(${list(by.map(([k, n]) => `${n} ${REFEREE[k].short}-graded`))}), all at or below ${pc(hits.at(-1).p)}` +
    `${miss.length ? `; the ${miss.length} misses were given ${pc(miss[0].p)} to ${pc(miss.at(-1).p)}` : ""}.` +
    `${none.length ? ` No ${list(none.map((k) => REFEREE[k].short + "-graded"))} bet came true.` : ""}`;
}

// ---------- the prior (ledger/prior.md's first table, as written; rule 14) ----------
// The first "## " section after "In plain English" that holds a table: its heading, its explaining sentence(s) and the
// table, rendered from the file, never retyped here. The headline sentence comes from the file's plain-English section.
async function drawPrior() {
  const box = el("prior");
  const md = await loadPriorMd();
  if (!md) { box.innerHTML = `<div class="empty">No <code>ledger/prior.md</code> yet (run <code>python3 ledger/prior.py</code>).</div>`; return; }
  const parts = md.replace(/^#\s+.*\n/, "").split(/\n(?=##\s)/);
  const plain = parts.find((x) => /^##\s+in plain english/i.test(x.trim()));
  const first = parts.find((x) => /^##\s/.test(x.trim()) && !/^##\s+in plain english/i.test(x.trim()) && /\n\|.*\|\s*\n\|[\s:|-]+\|/.test(x));
  const lead = plain ? (plain.replace(/^##.*\n/, "").trim().split(/\n\s*\n/)[0] || "") : "";
  if (!first) { box.innerHTML = `<div class="empty"><code>ledger/prior.md</code> has no table yet.</div>`; return; }
  box.innerHTML = (lead ? window.marked.parse(lead) : "") + window.marked.parse(first.replace(/^##\s/, "### ")) +
    `<p class="muted small">Read from <code>ledger/prior.md</code>, generated by <code>ledger/prior.py</code> from the ledger. ` +
    `The file also splits the record by referee, cost, source and map layer, and lists programs due a closing review.</p>`;
  wrapTables(box);
}

// ---------- page ----------
drawPrior();
(async () => {
  const [md, bets] = await Promise.all([loadBrierMd(), loadBets()]);
  const data = readBrier(md, bets);
  const { scores, points } = data;
  const e = scores.engine, h = scores.human;
  const fmt = (v, d = 3) => (v == null ? "—" : v.toFixed(d));
  const enginePts = points.filter((p) => p.side === "engine"), humanPts = points.filter((p) => p.side === "human");
  const engineN = enginePts.length;
  el("stats").innerHTML = [
    stat("Engine's Brier score", fmt(e?.brier), `Lower is better. Always saying 50% scores ${fmt(e?.half ?? 0.25)}.`),
    stat("Hits expected → got", e?.expected != null ? `${fmt(e.expected, 2)} → ${e.observed}` : "—", `Over ${engineN} scored bet${engineN === 1 ? "" : "s"}.`),
    stat("Human's Brier score", humanPts.length ? fmt(brierOf(humanPts)) : "—", humanPts.length ? `Over ${humanPts.length} bets.` : `No human odds on any of the ${enginePts.length} scored bets.`),
    stat("Bets in the ledger", String(bets.length || "—"), `${enginePts.length} have both stated odds and an outcome decided by their pre-registered rule.`),
  ].join("");
  // Rule 15: both numbers, one plain sentence.
  if (data.secondary.length) {
    const all = enginePts.map((p) => ({ p: p.p, o: p.o })).concat(data.secondary);
    el("stats").insertAdjacentHTML("afterend", `<p class="how">Some tests were scored more than once on the same run, so one lucky run counted several times; counting each run once, the engine's Brier score is ${fmt(brierOf(enginePts))} on ${engineN} bets, and counting every scored row as before it is ${fmt(brierOf(all))} on ${all.length} (the ${data.secondary.length} repeats: ${data.secondary.map((x) => `${esc(x.id)} on ${esc(x.of)}'s run`).join(", ")}).</p>`);
  }
  // brier.md is generated from the same file; if the two disagree, say so rather than pick one silently.
  if (e?.n != null && e.n !== enginePts.length)
    el("stats").insertAdjacentHTML("afterend", `<p class="muted small">Note: <code>brier.md</code> counts ${e.n} scored bets and <code>bets.jsonl</code> ${enginePts.length}; <code>brier.md</code> is regenerated on the next deploy.</p>`);
  const refs = ["model", "chip", "record"].map((k) => ({ k, pts: enginePts.filter((p) => p.ref === k) })).filter((r) => r.pts.length);
  el("byref").innerHTML = refs.map(({ k, pts }) => {
    const hitsN = pts.filter((p) => p.o).length, exp = pts.reduce((a, p) => a + p.p, 0);
    return `<div class="stat"><div class="label">${refKey(k, 15)} ${esc(REFEREE[k].word)}</div><div class="value">${fmt(brierOf(pts))}</div>
      <div class="note">Brier on ${pts.length} bet${pts.length === 1 ? "" : "s"}; ${hitsN} came true, ${fmt(exp, 2)} expected. ${esc(REFEREE[k].what[0].toUpperCase() + REFEREE[k].what.slice(1))}.</div></div>`;
  }).join("");
  el("hitsline").innerHTML = hitsSentence(enginePts);

  if (points.length) {
    drawChart(data);
    let lw = window.innerWidth;
    window.addEventListener("resize", () => { if (Math.abs(window.innerWidth - lw) > 40) { lw = window.innerWidth; drawChart(data); } });
  }
  else el("chart").innerHTML = `<div class="empty">No scored bets yet. The chart is drawn from <code>ledger/brier.md</code>.</div>`;
  const hasHuman = points.some((p) => p.side === "human");
  el("chartkey").innerHTML = ["model", "chip", "record"].filter((k) => enginePts.some((p) => p.ref === k))
    .map((k) => `<span>${refKey(k, 16)}<b>${esc(REFEREE[k].word)}</b>&nbsp;<span class="muted">${enginePts.filter((p) => p.ref === k).length}</span></span>`).join("") +
    `<span><svg width="18" height="18"><path d="M9 1l8 8-8 8-8-8z" fill="#bcb8ae"/></svg><b>Bucket</b>&nbsp;<span class="muted">all referees pooled; the bar is its 95% interval</span></span>` +
    (hasHuman ? `<span><svg width="16" height="16"><circle cx="8" cy="8" r="7" fill="${SIDE.human.hex}"/></svg><b>Human</b></span>`
      : `<span class="muted">no human odds, so no human dots</span>`);

  if (!md) { el("plain").innerHTML = `<div class="empty">No <code>ledger/brier.md</code> yet.</div>`; return; }
  // Plain English first, then the full scorecard.
  const body = md.replace(/^#\s+.*\n/, "");
  const parts = body.split(/\n(?=##\s)/);
  const plainIdx = parts.findIndex((p) => /^##\s+in plain english/i.test(p.trim()));
  if (plainIdx >= 0) {
    el("plain").innerHTML = `<h2>What it says</h2>` + window.marked.parse(parts[plainIdx].replace(/^##.*\n/, ""));
    parts.splice(plainIdx, 1);
  }
  el("full").innerHTML = `<h2>The full scorecard</h2><p class="muted small">Shown as written in <code>ledger/brier.md</code>. ${data.source === "bets.jsonl" ? "The chart above was computed from <code>bets.jsonl</code> because brier.md had no per-bet table." : ""}</p>` +
    window.marked.parse(parts.join("\n").replace(/^##\s/gm, "### "));
  wrapTables(el("full"));
})();
